        "--input",
        "tests/fixtures/six-player-mvp/sample/locale-unrecorded/god.replay.json",
        "--output",
        "/tmp/unused-frame.png",
        "--frame=-1",
      ],
      "replay_frame_invalid",
    ],
  ] as const) {
    const result = await command(script, [...args]);
