/**
 * 负责玩家回合归档的错误诊断字段白名单与结构读取。输入为未知诊断数据，输出为已校验
 * 的描述符值快照或精确字段校验错误；本契约只保存分类、状态码、重试信息和文件错误码。
 * 不序列化 Error、堆栈或供应商原始响应，不实施重试、读取文件或授予适配器运行权限。
 * 直接断言检查传入值，reader 先复制数据描述符再验证同一返回快照；二者边界不能混淆。
 */
import { assertField, isRecord } from "./validation";

/** 可归档诊断分类白名单；机器标识保持稳定，诊断事实不携带原始异常或供应商响应。 */
export const ERROR_DIAGNOSTIC_CODES = [
  "transport_error",
  "request_timeout",
  "request_aborted",
  "rate_limited",
  "authentication_failed",
  "permission_denied",
  "model_unavailable",
  "network_error",
  "filesystem_error",
  "action_failed",
] as const;
export type ErrorDiagnosticCode = (typeof ERROR_DIAGNOSTIC_CODES)[number];
export const FILE_ERROR_CODES = [
  "EACCES",
  "EPERM",
  "ENOENT",
  "ENOSPC",
  "EROFS",
  "EEXIST",
  "EMFILE",
  "ENFILE",
  "EIO",
] as const;
export interface ErrorDiagnostic {
  code: ErrorDiagnosticCode;
  statusCode?: number;
  retryable?: boolean;
  /** 记录已知等待建议，合法范围为零到一天；存在该字段不表示系统已经或必须重试。 */
  retryAfterMs?: number;
  fileCode?: (typeof FILE_ERROR_CODES)[number];
}
const diagnosticFields = ["code", "statusCode", "retryable", "retryAfterMs", "fileCode"] as const;
/** 只检查既有字段与范围，失败仍指向原精确路径；不把缺席字段补为默认重试政策。 */
export function assertErrorDiagnostic(
  value: unknown,
  path = "diagnostic",
): asserts value is ErrorDiagnostic {
  assertField(isRecord(value), path);
  assertField(
    typeof value.code === "string" &&
      ERROR_DIAGNOSTIC_CODES.includes(value.code as ErrorDiagnosticCode),
    `${path}.code`,
  );
  for (const key of Object.keys(value))
    assertField(
      diagnosticFields.includes(key as (typeof diagnosticFields)[number]),
      `${path}.${key}`,
    );
  assertField(
    value.statusCode === undefined ||
      (typeof value.statusCode === "number" &&
        Number.isInteger(value.statusCode) &&
        value.statusCode >= 100 &&
        value.statusCode <= 599),
    `${path}.statusCode`,
  );
  assertField(
    value.retryable === undefined || typeof value.retryable === "boolean",
    `${path}.retryable`,
  );
  assertField(
    value.retryAfterMs === undefined ||
      (typeof value.retryAfterMs === "number" &&
        Number.isSafeInteger(value.retryAfterMs) &&
        value.retryAfterMs >= 0 &&
        value.retryAfterMs <= 86_400_000),
    `${path}.retryAfterMs`,
  );
  assertField(
    value.fileCode === undefined ||
      (typeof value.fileCode === "string" &&
        FILE_ERROR_CODES.includes(value.fileCode as (typeof FILE_ERROR_CODES)[number])),
    `${path}.fileCode`,
  );
}

/** 按原数据描述符复制诊断元数据，再校验同一返回快照；不执行字段 getter。 */
export function readErrorDiagnostic(value: unknown): ErrorDiagnostic {
  assertField(isRecord(value), "diagnostic");
  const snapshot: Record<string, unknown> = {};
  for (const [key, descriptor] of Object.entries(Object.getOwnPropertyDescriptors(value))) {
    assertField(
      diagnosticFields.includes(key as (typeof diagnosticFields)[number]) && "value" in descriptor,
      `diagnostic.${key}`,
    );
    snapshot[key] = descriptor.value;
  }
  assertErrorDiagnostic(snapshot);
  return snapshot;
}

/**
 * 向后端和浏览器公开原 schema 2 复盘、历史转换与显式封装 reader；输入为纯数据归档。
 * 输出保留原规范化 document，旧未声明／v1／v2 reader 规则与原文不变；新封装身份不表示可执行授权。
 * 游戏结算与严格来源兼容仍由后端实际执行器负责，本出口不导入 Node、World 或 renderer。
 */
import { isRecord, assertField, assertSerializedData, ReplayDocumentValidationError } from "./validation";
export { ReplayDocumentValidationError } from "./validation";
import { isLocale, type Locale, type SealedVictoryResult } from "@ai-werewolf-arena/game-contract";
import { unwrapRecordingEnvelope, type RecordingIdentities } from "./archive-envelope";
import { readVictoryResult } from "./outcomes";
import {
  legacyPhaseId,
  legacyStageId,
  legacyRoleId,
  legacyCampId,
  legacyResultReasonId,
} from "./legacy_aliases";
export * from "./legacy_aliases";
export const REPLAY_SCHEMA_VERSION = 2 as const;
export * from "./inspection";
export * from "./gravekeeper";
export * from "./outcomes";

/**
 * 浏览器与视频消费的公开复盘数据形状；展示视图不充当已持久化完整归档。
 *
 * `god` 为完整裁判视角，包含每个角色和所有公开事件，
 * 也支持仍进行中的对局；执行来源与版本声明由新 envelope 独立记录。
 */
export type ReplayPerspective = "god";

export interface ReplayEvent {
  seq: number;
  timestamp: string;
  phase: string;
  day: number;
  stage?: string;
  type: string;
  payload: Record<string, unknown>;
}

export interface ReplayDocument {
  schemaVersion: typeof REPLAY_SCHEMA_VERSION;
  sessionId: string;
  perspective: ReplayPerspective;
  meta: {
    locale?: Locale;
    board: string;
    startedAt: string;
    endedAt: string;
  };
  result: {
    winner: string | null;
    reason: string | null;
    /** 明确的引擎判胜，与执行结束原因分别记录。 */
    decision?: SealedVictoryResult;
  };
  players: Array<{
    player_id: number;
    role: string;
    camp: string;
    name?: string;
  }>;
  events: ReplayEvent[];
}

/** 校验未筛选的原规范 document，事件序号从一开始；不推导游戏规则。 */
function assertReplayShape(
  value: unknown,
): asserts value is Omit<ReplayDocument, "schemaVersion"> & { schemaVersion?: unknown } {
  if (
    !isRecord(value) ||
    value.perspective !== "god" ||
    typeof value.sessionId !== "string" ||
    !Array.isArray(value.events)
  ) {
    throw new ReplayDocumentValidationError("invalid_document", "document");
  }
  if (!isRecord(value.meta) || !isRecord(value.result) || !Array.isArray(value.players)) {
    throw new ReplayDocumentValidationError("missing_fields", "meta/result/players");
  }

  assertField(value.meta.locale === undefined || isLocale(value.meta.locale), "meta.locale");
  assertField(typeof value.meta.board === "string", "meta.board");
  assertField(typeof value.meta.startedAt === "string", "meta.startedAt");
  assertField(typeof value.meta.endedAt === "string", "meta.endedAt");
  assertField(
    value.result.winner === null || typeof value.result.winner === "string",
    "result.winner",
  );
  assertField(
    value.result.reason === null || typeof value.result.reason === "string",
    "result.reason",
  );

  const playerIds = new Set<number>();
  for (let index = 0; index < value.players.length; index += 1) {
    const player: unknown = value.players[index];
    const path = `players[${index}]`;
    assertField(isRecord(player), path);
    assertField(
      typeof player.player_id === "number" &&
        Number.isSafeInteger(player.player_id) &&
        player.player_id > 0,
      `${path}.player_id`,
    );
    assertField(!playerIds.has(player.player_id), `${path}.player_id`);
    playerIds.add(player.player_id);
    assertField(typeof player.role === "string", `${path}.role`);
    assertField(typeof player.camp === "string", `${path}.camp`);
    assertField(player.name === undefined || typeof player.name === "string", `${path}.name`);
  }

  for (let index = 0; index < value.events.length; index += 1) {
    const event: unknown = value.events[index];
    const path = `events[${index}]`;
    assertField(isRecord(event), path);
    assertField(event.seq === index + 1, `${path}.seq`);
    assertField(typeof event.timestamp === "string", `${path}.timestamp`);
    assertField(typeof event.phase === "string", `${path}.phase`);
    assertField(
      typeof event.day === "number" && Number.isSafeInteger(event.day) && event.day >= 0,
      `${path}.day`,
    );
    assertField(event.stage === undefined || typeof event.stage === "string", `${path}.stage`);
    assertField(typeof event.type === "string", `${path}.type`);
    assertField(isRecord(event.payload), `${path}.payload`);
  }
  const decision = Object.getOwnPropertyDescriptor(value.result, "decision");
  if (decision) {
    assertField("value" in decision && decision.enumerable === true, "result.decision");
    const parsed = readVictoryResult(decision.value, [...playerIds]);
    assertField(parsed.winner === value.result.winner, "result.winner");
  }
  const explicit: SealedVictoryResult[] = [];
  if (decision && "value" in decision)
    explicit.push(readVictoryResult(decision.value, [...playerIds]));
  for (const event of value.events) {
    if (
      event.type !== "game_over" ||
      !isRecord(event.payload) ||
      (!Object.hasOwn(event.payload, "outcome") && !Object.hasOwn(event.payload, "decidedAt"))
    )
      continue;
    assertSerializedData(event.payload, "events.game_over.payload");
    try {
      explicit.push(readVictoryResult(event.payload, [...playerIds]));
    } catch {
      /* 独立非法终局事实继续保留为未知原事件，不生成替代判胜。 */
    }
  }
  if (explicit.length > 1)
    assertField(
      explicit.every((item) => JSON.stringify(item) === JSON.stringify(explicit[0])),
      "result.decision_terminal_mismatch",
    );
}

/** 原 canonical v2 writer 契约；历史文件及显式新封装由 reader 单独判版本。 */
export function assertReplayDocument(value: unknown): asserts value is ReplayDocument {
  if (value !== null && typeof value === "object") assertSerializedData(value, "document");
  assertReplayShape(value);
  if (value.schemaVersion !== REPLAY_SCHEMA_VERSION)
    throw new ReplayDocumentValidationError("unsupported_version", "schemaVersion");
}

/** 只读转换，先判封装和内层版本再解释历史别名；昵称、发言等用户原文不改写。 */
export function readReplayDocument(value: unknown): ReplayDocument {
  if (value !== null && typeof value === "object") assertSerializedData(value, "document");
  value = unwrapRecordingEnvelope(value, "public_replay").payload;
  if (!isRecord(value)) throw new ReplayDocumentValidationError("invalid_document", "document");
  const version = value.schemaVersion;
  if (version !== undefined && version !== 1 && version !== REPLAY_SCHEMA_VERSION)
    throw new ReplayDocumentValidationError("unsupported_version", "schemaVersion");
  assertReplayShape(value);
  if (version === REPLAY_SCHEMA_VERSION) {
    const result = structuredClone(value);
    assertReplayDocument(result);
    return result as ReplayDocument;
  }
  const result = structuredClone(value) as ReplayDocument;
  result.schemaVersion = REPLAY_SCHEMA_VERSION;
  result.players = result.players.map((player) => ({
    ...player,
    role: legacyRoleId(player.role),
    camp: legacyCampId(player.camp),
  }));
  result.result.winner = result.result.winner === null ? null : legacyCampId(result.result.winner);
  result.result.reason =
    result.result.reason === null ? null : legacyResultReasonId(result.result.reason);
  result.events = result.events.map((event) => {
    const payload = { ...event.payload };
    if (event.type === "phase_changed" && typeof payload.phase === "string")
      payload.phase = legacyPhaseId(payload.phase);
    if (event.type === "game_over" || event.type === "phase_changed") {
      if (typeof payload.winner === "string") payload.winner = legacyCampId(payload.winner);
      if (typeof payload.reason === "string") payload.reason = legacyResultReasonId(payload.reason);
    }
    if (event.type === "god_private_game_info" && Array.isArray(payload.players))
      payload.players = payload.players.map((player) =>
        isRecord(player)
          ? {
              ...player,
              ...(typeof player.role === "string" ? { role: legacyRoleId(player.role) } : {}),
              ...(typeof player.camp === "string" ? { camp: legacyCampId(player.camp) } : {}),
            }
          : player,
      );
    return {
      ...event,
      phase: legacyPhaseId(event.phase),
      ...(event.stage === undefined ? {} : { stage: legacyStageId(event.stage) }),
      payload,
    };
  });
  assertReplayDocument(result);
  return result;
}

export * from "./player_record";

export * from "./error_diagnostic";

export * from "./archive-envelope";

/** 前端 canonical 入口保留声明供真实展示支持检查；旧裸档返回 null，不猜造历史身份。 */
export function readReplayArchive(value: unknown): { replay: ReplayDocument; identities: RecordingIdentities | null } {
  if (value !== null && typeof value === "object") assertSerializedData(value, "document");
  const archive = unwrapRecordingEnvelope(value, "public_replay");
  return { replay: readReplayDocument(archive.payload), identities: archive.identities };
}

export * from "./manifest";

/**
 * 负责玩家私有时间线的原 schema 2 验证、历史别名转换和新 player envelope 准入。
 * 输入为旧无声明／v1／v2 或显式新封装；输出保留原 prompt、工具、模型原文及 player 局部序号。
 * 新声明必须符合当前请求／展示数据协议；不把纯声明当真实来源签名或行动许可，不导入 renderer。
 */
import { unwrapRecordingEnvelope, assertCurrentRecordingContracts } from "./archive-envelope";
import { assertErrorDiagnostic, type ErrorDiagnostic } from "./error_diagnostic";
import { assertField, isRecord, ReplayDocumentValidationError } from "./validation";
import { isLocale, type Locale } from "@ai-werewolf-arena/game-contract";
import { legacyPhaseId, legacyStageId, legacyRoleId, legacyCampId } from "./legacy_aliases";

/** 玩家单回合增量消息。 */
export interface ReplayPlayerDeltaMessage {
  role: "system" | "user" | "assistant" | "tool" | "meta";
  kind:
    | "prompt"
    | "retry_prompt"
    | "assistant_output"
    | "request_error"
    | "constraint_warning"
    | "tool_call"
    | "tool_result"
    | "action_summary"
    | "fallback";
  attempt?: number;
  diagnostic?: ErrorDiagnostic;
  content?: string;
  name?: string;
  args?: Record<string, unknown>;
  accepted?: boolean;
  result?: Record<string, unknown> | string;
}

/** 玩家视角下的结构化事件时间线条目。 */
export interface ReplayPlayerEventEntry {
  seq: number;
  kind: "event";
  day: number;
  phase: string;
  stage: string;
  request_id: string;
  timestamp?: string;
  /** 仅供复盘与审计关联领域事件；不会进入玩家 Agent 协议。 */
  source_event_seq?: number;
  event: { seq: number; type: string; payload: Record<string, unknown> };
}

/** 玩家回合时间线条目。 */
export interface ReplayPlayerTurnEntry {
  seq: number;
  kind: "turn";
  day: number;
  phase: string;
  stage: string;
  request_id: string;
  timestamp?: string;
  turn_seq: number;
  delta_messages: ReplayPlayerDeltaMessage[];
}

/** 玩家时间线条目联合类型。 */
export type ReplayPlayerTimelineEntry = ReplayPlayerEventEntry | ReplayPlayerTurnEntry;

/** 玩家视角复盘结构。 */
export interface ReplayPlayerView {
  schemaVersion?: 2;
  locale?: Locale;
  player_id: number;
  role: string;
  camp: string;
  initial_prompt?: {
    day: number;
    phase: string;
    stage: string;
    request_id: string;
    timestamp?: string;
    prompt_system?: string;
    board_info?: string;
    prompt_user?: string[];
  };
  timeline: ReplayPlayerTimelineEntry[];
}

export type CanonicalReplayPlayerView = ReplayPlayerView & { schemaVersion: 2 };

/** 校验原内层 wire 字段，不改写模型或玩家原文；缺席身份不被补造成当前来源。 */
function assertPlayerShape(value: unknown): asserts value is ReplayPlayerView {
  assertField(isRecord(value), "player.document");
  assertField(
    typeof value.player_id === "number" &&
      Number.isSafeInteger(value.player_id) &&
      value.player_id > 0,
    "player.player_id",
  );
  assertField(typeof value.role === "string", "player.role");
  assertField(typeof value.camp === "string", "player.camp");
  assertField(value.locale === undefined || isLocale(value.locale), "player.locale");
  assertField(Array.isArray(value.timeline), "player.timeline");
  const metadata = (entry: Record<string, unknown>, path: string) => {
    assertField(typeof entry.day === "number" && Number.isSafeInteger(entry.day), `${path}.day`);
    assertField(typeof entry.phase === "string", `${path}.phase`);
    assertField(typeof entry.stage === "string", `${path}.stage`);
    assertField(typeof entry.request_id === "string", `${path}.request_id`);
    assertField(
      entry.timestamp === undefined || typeof entry.timestamp === "string",
      `${path}.timestamp`,
    );
  };
  if (value.initial_prompt !== undefined) {
    assertField(isRecord(value.initial_prompt), "player.initial_prompt");
    metadata(value.initial_prompt, "player.initial_prompt");
    for (const field of ["prompt_system", "board_info"])
      assertField(
        value.initial_prompt[field] === undefined ||
          typeof value.initial_prompt[field] === "string",
        `player.initial_prompt.${field}`,
      );
    assertField(
      value.initial_prompt.prompt_user === undefined ||
        (Array.isArray(value.initial_prompt.prompt_user) &&
          value.initial_prompt.prompt_user.every((item) => typeof item === "string")),
      "player.initial_prompt.prompt_user",
    );
  }
  for (let index = 0; index < value.timeline.length; index++) {
    const entry: unknown = value.timeline[index];
    const path = `player.timeline[${index}]`;
    assertField(isRecord(entry), path);
    metadata(entry, path);
    assertField(entry.seq === index + 1, `${path}.seq`);
    if (entry.kind === "event") {
      assertField(isRecord(entry.event), `${path}.event`);
      assertField(
        typeof entry.event.seq === "number" &&
          Number.isSafeInteger(entry.event.seq) &&
          entry.event.seq > 0,
        `${path}.event.seq`,
      );
      assertField(
        typeof entry.event.type === "string" && isRecord(entry.event.payload),
        `${path}.event.type/payload`,
      );
      assertField(
        entry.source_event_seq === undefined ||
          (typeof entry.source_event_seq === "number" &&
            Number.isSafeInteger(entry.source_event_seq) &&
            entry.source_event_seq > 0),
        `${path}.source_event_seq`,
      );
    } else {
      assertField(entry.kind === "turn", `${path}.kind`);
      assertField(
        typeof entry.turn_seq === "number" &&
          Number.isSafeInteger(entry.turn_seq) &&
          entry.turn_seq > 0,
        `${path}.turn_seq`,
      );
      assertField(Array.isArray(entry.delta_messages), `${path}.delta_messages`);
      for (const [messageIndex, message] of entry.delta_messages.entries()) {
        const messagePath = `${path}.delta_messages[${messageIndex}]`;
        assertField(isRecord(message), messagePath);
        assertField(
          typeof message.role === "string" &&
            ["system", "user", "assistant", "tool", "meta"].includes(message.role),
          `${messagePath}.role`,
        );
        assertField(
          typeof message.kind === "string" &&
            [
              "prompt",
              "retry_prompt",
              "assistant_output",
              "request_error",
              "constraint_warning",
              "tool_call",
              "tool_result",
              "action_summary",
              "fallback",
            ].includes(message.kind),
          `${messagePath}.kind`,
        );
        for (const field of ["content", "name"])
          assertField(
            message[field] === undefined || typeof message[field] === "string",
            `${messagePath}.${field}`,
          );
        if (message.diagnostic !== undefined)
          assertErrorDiagnostic(message.diagnostic, `${messagePath}.diagnostic`);
        assertField(
          message.attempt === undefined ||
            (typeof message.attempt === "number" &&
              Number.isSafeInteger(message.attempt) &&
              message.attempt >= 0),
          `${messagePath}.attempt`,
        );
        assertField(message.args === undefined || isRecord(message.args), `${messagePath}.args`);
        assertField(
          message.accepted === undefined || typeof message.accepted === "boolean",
          `${messagePath}.accepted`,
        );
        assertField(
          message.result === undefined ||
            typeof message.result === "string" ||
            isRecord(message.result),
          `${messagePath}.result`,
        );
      }
    }
  }
}

export function assertReplayPlayerView(value: unknown): asserts value is CanonicalReplayPlayerView {
  assertPlayerShape(value);
  if (value.schemaVersion !== 2)
    throw new ReplayDocumentValidationError("unsupported_version", "player.schemaVersion");
}

export function readReplayPlayerView(value: unknown): CanonicalReplayPlayerView {
  const archive = unwrapRecordingEnvelope(value, "player_view");
  if (archive.identities) assertCurrentRecordingContracts(archive.identities);
  value = archive.payload;
  if (!isRecord(value))
    throw new ReplayDocumentValidationError("invalid_document", "player.document");
  if (value.schemaVersion !== undefined && value.schemaVersion !== 1 && value.schemaVersion !== 2)
    throw new ReplayDocumentValidationError("unsupported_version", "player.schemaVersion");
  const snapshot = structuredClone(value);
  if (
    snapshot.schemaVersion !== undefined &&
    snapshot.schemaVersion !== 1 &&
    snapshot.schemaVersion !== 2
  )
    throw new ReplayDocumentValidationError("unsupported_version", "player.schemaVersion");
  const alreadyCurrent = snapshot.schemaVersion === 2;
  assertPlayerShape(snapshot);
  const result = snapshot as CanonicalReplayPlayerView;
  result.schemaVersion = 2;
  if (alreadyCurrent) return result;
  result.role = legacyRoleId(result.role);
  result.camp = legacyCampId(result.camp);
  const normalize = <T extends { phase: string; stage: string }>(entry: T): T => ({
    ...entry,
    phase: legacyPhaseId(entry.phase),
    stage: legacyStageId(entry.stage),
  });
  if (result.initial_prompt) result.initial_prompt = normalize(result.initial_prompt);
  result.timeline = result.timeline.map((entry) => normalize(entry));
  return result;
}
